mapper.select:
SELECT id, assessment_name AS assessmentName, patient_name AS patientName, gender, age, medical_record_number AS medicalRecordNumber, disease_type AS diseaseType, enrollment_institution AS enrollmentInstitution, execution_institution AS executionInstitution, status, prescribing_doctor AS prescribingDoctor, created_time AS createdTime FROM assessment_execution_record
AND disease_type = #{query.diseaseType}
AND status = #{query.status}
AND enrollment_institution = #{query.enrollmentInstitution}
AND execution_institution = #{query.executionInstitution}
AND ( patient_name LIKE CONCAT('%', #{query.searchKeyword}, '%') OR medical_record_number LIKE CONCAT('%', #{query.searchKeyword}, '%') )
ORDER BY created_time DESC
